$ErrorActionPreference='Stop';$root=Split-Path -Parent $PSScriptRoot;$relative='src/main/java/com/simibubi/create/foundation/blockEntity/renderer/SmartBlockEntityRenderer.java';$ref=[IO.File]::ReadAllText((Join-Path $root "baseline-reference/$relative"));$src=[IO.File]::ReadAllText((Join-Path $root "source/fabric/$relative"));$fromStart=$ref.LastIndexOf("`t@Override");$toStart=$src.LastIndexOf("`t@Override");if($fromStart-lt 0-or$toStart-lt 0){throw 'Smart renderer tail anchors missing'};$from=$ref.Substring($fromStart);$to=$src.Substring($toStart);$p=Join-Path $root 'port-changes.json';$m=Get-Content $p -Raw|ConvertFrom-Json;$e=$m.files|Where-Object path -eq 'foundation/blockEntity/renderer/SmartBlockEntityRenderer.java';$existing=@($e.changes);$e.changes=@($existing[0..($existing.Count-2)])+[pscustomobject]@{from=$from;to=$to};$m|ConvertTo-Json -Depth 20|Set-Content $p -Encoding utf8;Write-Output 'Narrowed Smart renderer provenance to its exact class tail.'
